using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioMultiHoverValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static StudioModelEditor ed;static StudioModelDocument doc;static SceneView view;static int checks;static RenderTexture rt;
 static object Call(string name,params object[] a)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==a.Length&&m.GetParameters().Select((p,i)=>a[i]==null||p.ParameterType.IsInstanceOfType(a[i])).All(b=>b)).Invoke(ed,a);
 static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);static void Set(string n,object v)=>typeof(StudioModelEditor).GetField(n,F).SetValue(ed,v);static void Check(bool p,string m){if(!p)throw new Exception(m);checks++;}
 static void Query(Vector2 p){Call("ResetComponentHover");Set("hoverPreviewNode",-1);Set("hoverPreviewComponent",-1);Call("UpdateSelectedComponentHover",view,p);}
 static Color32[] Render(Vector2? pointer,string name){GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;if(pointer.HasValue)Query(pointer.Value);else{Call("ResetComponentHover");Set("hoverPreviewNode",-1);Set("hoverPreviewComponent",-1);}Call("DrawVisibleObjectWireframes",view.camera);Call("DrawComponents",view);var t=new Texture2D(600,600,TextureFormat.RGBA32,false);try{t.ReadPixels(new Rect(0,0,600,600),0,0);t.Apply();if(name!=null)File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../multi-hover-"+name+".png")),t.EncodeToPNG());return t.GetPixels32();}finally{Object.DestroyImmediate(t);}}
 public static void Run(){EditorApplication.delayCall+=()=>{try{doc=ScriptableObject.CreateInstance<StudioModelDocument>();for(int i=0;i<3;i++){var m=StudioModelDocument.BuildPrimitive(PrimitiveType.Quad,out var p);doc.nodes.Add(new StudioModelDocument.Node{mesh=m,cutPolygons=p,cutTriangles=m.triangles,position=Vector3.right*(i-1)*1.7f});}ed=new StudioModelEditor(()=>{});ed.Load(doc);view=ScriptableObject.CreateInstance<SceneView>();view.position=new Rect(100,100,650,650);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.identity,5);SceneView.duringSceneGui+=Draw;view.Repaint();}catch(Exception e){Finish(e.ToString());}};}
 static void Draw(SceneView s){if(s!=view||Event.current.type!=EventType.Repaint)return;SceneView.duringSceneGui-=Draw;rt=new RenderTexture(600,600,24);rt.Create();var old=RenderTexture.active;var target=view.camera.targetTexture;var rect=view.camera.pixelRect;GL.PushMatrix();string result;try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,600,600);Handles.SetCamera(new Rect(0,0,600,600),view.camera);RenderTexture.active=rt;GL.Viewport(new Rect(0,0,600,600));foreach(var mode in new[]{StudioModelEditor.ComponentMode.Vertex,StudioModelEditor.ComponentMode.Edge,StudioModelEditor.ComponentMode.Face}){for(int node=0;node<3;node++)Call("ActivateComponentTarget",node,mode);var baseline=Render(null,null);for(int node=0;node<3;node++){var vertices=doc.nodes[node].mesh.vertices;var local=mode==StudioModelEditor.ComponentMode.Vertex?vertices[0]:mode==StudioModelEditor.ComponentMode.Edge?(vertices[0]+vertices[1])*.5f:Vector3.zero;var pointer=HandleUtility.WorldToGUIPoint(ed.Transforms[node].TransformPoint(local));var pixels=Render(pointer,mode+"-"+node);Check((int)Get(ed,"hoverPreviewNode")==node,"Hover did not reach node "+node+" in "+mode);Check(ed.Active==2,"Hover changed active object");Check(((HashSet<int>)Get(ed,"objects")).SetEquals(new[]{0,1,2}),"Hover changed selected cohort");for(int other=0;other<3;other++){var state=Call("ComponentTargetAt",other,false);Check(((HashSet<int>)Get(state,"selection")).Count==0,"Hover selected components");Check(((int)Get(Get(state,"drawing"),"hoveredComponent")>=0)==(other==node),"Stale/missing per-object preview");}Check(pixels.Where((c,i)=>!c.Equals(baseline[i])).Count()>3,"No rendered hover difference");int uploads=ed.WireBatchUploads;Check(pixels.SequenceEqual(Render(pointer,null)),"Repeated preview changed");Check(ed.WireBatchUploads==uploads,"Hover reuploaded mesh wires");}Query(new Vector2(-10000,-10000));Check((int)Get(ed,"hoverPreviewNode")==-1,"Leaving meshes retained preview");}result="PASS "+checks+" three-object V/E/F hover query, rendered preview, state and cache checks";}catch(Exception e){result=e.ToString();}finally{view.camera.targetTexture=target;view.camera.pixelRect=rect;Handles.SetCamera(view.camera);GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(rt);}Finish(result);}
 static void Finish(string r){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../multi-hover-result.txt")),r);EditorApplication.delayCall+=()=>{if(view)view.Close();ed?.Dispose();EditorApplication.Exit(r.StartsWith("PASS")?0:1);};}
}
